head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil55220";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — completeYn
// TODO Stage2: 세션 키 실환경 확인(회신 11항 · user-info 계약에 없는 키) — session.user.corpUsrTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil55220.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_corpUsrTpCd", fn: function(){ return ($c.session.getUserInfo("corpUsrTpCd") ==='62'); } }, { id: "if_corpUsrTpCd_2", fn: function(){ return ($c.session.getUserInfo("corpUsrTpCd") ==='22'); } }, { id: "slc_prtdepoRsnCd", fn: function(){ return ((dma_basicComInfo.get("mktTpCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.mktTpCd"); })()) === '1'); } }, { id: "slc_prtdepoRsnMngrghtTpCd", fn: function(){ return ((dma_basicComInfo.get("mktTpCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.mktTpCd"); })()) === '1'); } }, { id: "c_otherwise_114", fn: function(){ return (!(((dma_basicComInfo.get("mktTpCd") ?? (() => { throw new Error("unresolved:" + "basicComInfo.mktTpCd"); })()) === '1'))); } }, { id: "if_corpUsrTpCd_3", fn: function(){ return ($c.session.getUserInfo("corpUsrTpCd") ==='22'); } }, { id: "btn_delete", fn: function(){ return (! (String(((dma_PrePrtDepo.get("prtdepoId") ?? (() => { throw new Error("unresolved:" + "PrePrtDepo.prtdepoId"); })())) == null ? '' : ((dma_PrePrtDepo.get("prtdepoId") ?? (() => { throw new Error("unresolved:" + "PrePrtDepo.prtdepoId"); })()))).length === 0)); } }, { id: "btn_cancel", fn: function(){ return ((String(((dma_pageContext.get("completeYn") ?? "")) == null ? '' : ((dma_pageContext.get("completeYn") ?? ""))).length === 0)); } }, { id: "c_otherwise_169", fn: function(){ return (!(((String(((dma_pageContext.get("completeYn") ?? "")) == null ? '' : ((dma_pageContext.get("completeYn") ?? ""))).length === 0)))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.onload();
        try {
            if (form.prtdepoShrsDsp.value == null) {
                for (let i = 0; i < form.prtdepoShrsDsp.length; i++) {
                    fn_ObjValueSetComma(form.prtdepoShrsDsp[i]);
                }
            } else {
                fn_ObjValueSetComma(form.prtdepoShrsDsp);
            }
        } catch (err2) { $c.exception.handleError(err2, { notify: 'none', context: 'jldfil55220' }); return; }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55220.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

