    for (let i = 1, ch = name.charAt(i);
        (i < name.length) && (flag); ch = name.charAt(++i)) {
        if (((ch >= '0') && (ch <= '9')) || (ch === '.'))
            {}
        else
            flag = false;
    }
    return flag;
};
